insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 16, '2026-07-31 19:08:09.174', '2026-07-31 19:08:09.174', 56, 4, '국가는 확정될 예술가의 범죄를.', '준서.김');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 20, '2026-07-31 19:08:09.174', '2026-07-31 19:08:09.174', 53, 15, '국제법규는 기능을 바에 아니한다. 행위시의 위하여.', '준서.윤');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 10, '2026-07-31 19:08:09.174', '2026-07-31 19:08:09.174', 10, 28, '때까지는 승인된 체결·공포된 의하여 노력하여야.', '건우.최');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 20, '2026-07-31 19:08:09.174', '2026-07-31 19:08:09.174', 55, 3, '정한다. 보호를 예술가의 모든 염려가 진다. 재외국민을.', '준서.임');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 49, '2026-07-31 19:08:09.174', '2026-07-31 19:08:09.174', 19, 6, '신체의 있을 승인된.', '지훈.임');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 4, '2026-07-31 19:08:09.174', '2026-07-31 19:08:09.174', 32, 11, '또는 대하여 저작자·발명가·과학기술자와.', '현우.최');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 41, '2026-07-31 19:08:09.174', '2026-07-31 19:08:09.174', 29, 14, '같은 국가는 기능을 경우와 신문의 비밀과 가진다..', '예준.최');
